package Theme;
use strict;
use warnings;
use Archive::Tar;
use File::Basename qw(dirname);
use File::Path qw(make_path);

# Install an uploaded theme tarball below $dest; returns the number of files written.
sub install {
    my ($tarball, $dest) = @_;
    my $tar = Archive::Tar->new($tarball) or die Archive::Tar->error;
    my $count = 0;
    for my $file ($tar->get_files) {
        next unless $file->is_file;
        my $target = "$dest/" . $file->full_path;
        make_path(dirname($target));
        open(my $out, '>', $target) or die "cannot write $target: $!";
        binmode $out;
        print {$out} $file->get_content;
        close $out;
        $count++;
    }
    return $count;
}

1;

use strict;
use warnings;
use Archive::Tar;
use File::Temp qw(tempdir);
use Test::More;
use Theme;

subtest installs_one_file => sub {
    my $dir = tempdir(CLEANUP => 1);
    my $tar = Archive::Tar->new;
    $tar->add_data('a.css', 'x');
    $tar->write("$dir/theme.tar");
    is(Theme::install("$dir/theme.tar", "$dir/out"), 1, 'one file');
};

done_testing;
